// Saves a public page as one static file: style sheets inlined as text, scripts, frames and remote pictures removed.
import { chromium } from 'playwright';
import { writeFileSync } from 'node:fs';
const [, , url, out] = process.argv;
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto(url, { waitUntil: 'load', timeout: 60000 });
await page.waitForTimeout(1500);
const html = await page.evaluate(() => {
  let css = '';
  for (const sheet of document.styleSheets) { try { if (sheet.disabled) continue; const media = sheet.media.mediaText; const text = [...sheet.cssRules].map((r) => r.cssText).join('\n'); css += media ? `@media ${media} {\n${text}\n}\n` : text + '\n'; } catch { /* a sheet from another site that forbids reading */ } }
  document.querySelectorAll('script, noscript, iframe, link[rel="stylesheet"], style, link[rel="preload"], link[rel="modulepreload"]').forEach((el) => el.remove());
  document.querySelectorAll('img').forEach((img) => { img.removeAttribute('srcset'); img.setAttribute('src', 'data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7'); });
