4. Save this text as scratch/run.t.ts (it opens each page from disk, blocks the network, sends every check into the page as text as the README says, gives tokenFit the tokens in KIT_TOKENS (default {}), and adds a 'holds' finding for the window walk so that a grade is possible):
// Usage: KIT_PAGES=a.html,b.html [KIT_WIDTHS=1280,320] [KIT_TOKENS='{"--ink":"#111"}'] [KIT_ONLY=fn1,fn2] [KIT_ALL=1] npx vitest run --config scratch/vitest.config.ts scratch/run.t.ts
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { chromium } from 'playwright';
import { it } from 'vitest';
import { KIT_RULES, grade } from '@refraction/kit';
import * as checks from '@refraction/kit/src/page-checks/index.js';
const lines: string[] = [];
const log = (...a: unknown[]): void => { lines.push(a.join(' ')); };
it('run', async () => {
  const browser = await chromium.launch(process.env.PW_CHROMIUM ? { executablePath: process.env.PW_CHROMIUM } : {});
  log('browser', browser.version());
  const tokens = JSON.parse(process.env.KIT_TOKENS ?? '{}');
  const only = process.env.KIT_ONLY?.split(',');
  for (const file of (process.env.KIT_PAGES ?? '').split(',')) for (const width of (process.env.KIT_WIDTHS ?? '1280,320').split(',').map(Number)) {
    const context = await browser.newContext({ viewport: { width, height: 800 }, deviceScaleFactor: 1 });
    await context.route('**/*', (route) => (route.request().url().startsWith('file:') || route.request().url().startsWith('data:') ? route.continue() : route.abort()));
    const page = await context.newPage();
    await page.goto(pathToFileURL(resolve(file)).href, { waitUntil: 'load' });
    await page.waitForTimeout(400);
    const findings: any[] = [];
    for (const fn of Object.keys(checks)) {
      if (only && !only.includes(fn)) continue;
      try { findings.push(...await page.evaluate(`(${(checks as any)[fn]})(document${fn === 'tokenFit' ? ', ' + JSON.stringify(tokens) : ''})`) as any[]); }
      catch (e) { log(`CRASH ${fn}: ${String(e).split('\n')[0]}`); }
    }
    log(`\n=== ${file} @ ${width}px`);
    log('title:', await page.title());
    for (const f of findings) if (process.env.KIT_ALL || f.status === 'fails' || f.status === 'could-not-measure') log(JSON.stringify(f));
    log('other:', findings.filter((f) => f.status !== 'fails' && f.status !== 'could-not-measure').map((f) => `${f.ruleId}=${f.status}${f.measured ? `(${f.measured})` : ''}`).join(' '));
    const g = grade([...findings, { ruleId: 'behavior-dialog-keys', status: 'holds' }], KIT_RULES);
    log('grade (with the window walk reported as holds):', g.grade, '|', g.reason);
    await context.close();
  }
  await browser.close();
  writeFileSync('scratch/out.txt', lines.join('\n') + '\n');
});

